        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison, proposed reduction, repetition qualifier, inspection timing and distinction between new orders and backlog repairs."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C039.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this bounded possibility claim."
    }
  },
  "rationale": "Persistent missing attachments from older orders can remain despite improvement in new orders, obscuring that improvement when interpreting attachment frequencies. This licenses the stated possibility and the distinction between new orders and backlog repairs.",
  "uncertainty": "The claim does not establish that backlogs actually obscured this comparison or quantify any masking effect.",
  "anomalies": []
}
